module graph_solver(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [7:0] row0,\n    input [7:0] row1,\n    input [7:0] row2,\n    input [7:0] row3,\n    input [7:0] row4,\n    input [7:0] row5,\n    input [7:0] row6,\n    input [7:0] row7,\n    output reg done,\n    output reg valid,\n    output reg [15:0] result\n);\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] CHECK_COMPLETE = 3'd1;\n    localparam [2:0] FIND_NONEDGE = 3'd2;\n    localparam [2:0] ASSIGN_LETTERS = 3'd3;\n    localparam [2:0] VERIFY = 3'd4;\n    localparam [2:0] DONE_STATE = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [7:0] adjacency [0:7];\n    reg [1:0] assignments [0:7];\n    reg [2:0] u, v;\n    reg [2:0] n_reg;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd150;\n\n    integer i, j, k;\n    reg temp_complete;\n    reg temp_nonedge_found;\n    reg temp_verify_ok;\n    reg [1:0] abs_diff;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            valid <= 1'b0;\n            result <= 16'd0;\n            cycle_count <= 8'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                adjacency[i] <= 8'd0;\n                assignments[i] <= 2'd0;\n            end\n            n_reg <= 3'd0;\n            u <= 3'd0;\n            v <= 3'd0;\n        end else begin\n            state <= next_state;\n            if (state == IDLE && next_state == IDLE)\n                cycle_count <= 8'd0;\n            else\n                cycle_count <= cycle_count + 8'd1;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    valid <= 1'b0;\n                    if (start) begin\n                        adjacency[0] <= row0;\n                        adjacency[1] <= row1;\n                        adjacency[2] <= row2;\n                        adjacency[3] <= row3;\n                        adjacency[4] <= row4;\n                        adjacency[5] <= row5;\n                        adjacency[6] <= row6;\n                        adjacency[7] <= row7;\n                        n_reg <= n;\n                        next_state <= CHECK_COMPLETE;\n                    end else\n                        next_state <= IDLE;\n                end\n\n                CHECK_COMPLETE: begin\n                    temp_complete = 1'b1;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (i < n_reg && j < n_reg && i != j && adjacency[i][j] == 1'b0)\n                                temp_complete = 1'b0;\n                        end\n                    end\n                    if (temp_complete) begin\n                        for (k = 0; k < 8; k = k + 1)\n                            if (k < n_reg)\n                                assignments[k] <= 2'd0;\n                        next_state <= VERIFY;\n                    end else\n                        next_state <= FIND_NONEDGE;\n                end\n\n                FIND_NONEDGE: begin\n                    temp_nonedge_found = 1'b0;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (i < n_reg && j < n_reg && i != j && !temp_nonedge_found) begin\n                                if (adjacency[i][j] == 1'b0) begin\n                                    u <= i[2:0];\n                                    v <= j[2:0];\n                                    temp_nonedge_found = 1'b1;\n                                end\n                            end\n                        end\n                    end\n                    if (temp_nonedge_found)\n                        next_state <= ASSIGN_LETTERS;\n                    else begin\n                        valid <= 1'b0;\n                        next_state <= DONE_STATE;\n                    end\n                end\n\n                ASSIGN_LETTERS: begin\n                    assignments[u] <= 2'd0;\n                    assignments[v] <= 2'd2;\n                    for (k = 0; k < 8; k = k + 1) begin\n                        if (k < n_reg && k != u && k != v) begin\n                            if (adjacency[k][u] && !adjacency[k][v])\n                                assignments[k] <= 2'd0;\n                            else if (adjacency[k][v] && !adjacency[k][u])\n                                assignments[k] <= 2'd2;\n                            else\n                                assignments[k] <= 2'd1;\n                        end\n                    end\n                    next_state <= VERIFY;\n                end\n\n                VERIFY: begin\n                    temp_verify_ok = 1'b1;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (i < n_reg && j < n_reg && i != j) begin\n                                abs_diff = (assignments[i] > assignments[j]) ? assignments[i] - assignments[j] : assignments[j] - assignments[i];\n                                if (adjacency[i][j] != 1'b0) begin\n                                    if (abs_diff > 2'd1) temp_verify_ok = 1'b0;\n                                end else begin\n                                    if (abs_diff <= 2'd1) temp_verify_ok = 1'b0;\n                                end\n                            end\n                        end\n                    end\n                    valid <= temp_verify_ok;\n                    next_state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        if (i < n_reg)\n                            result[2*i +: 2] <= assignments[i];\n                        else\n                            result[2*i +: 2] <= 2'd0;\n                    end\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n\n            if (cycle_count >= MAX_CYCLES && state != IDLE) begin\n                next_state <= DONE_STATE;\n                valid <= 1'b0;\n            end\n        end\n    end\nendmodule